use crate::*;
use crate::owned::NativeRecordStorage;
use semio_framework_value_testing_admission::{EffectBank,Wallet};
type Turn<T=RetainedCloneStep>=RetainedWorkOutcome<T,ValueError>;
fn law()->serde_json::Value{serde_json::from_str(include_str!("../📐️.json")).unwrap()}
use crate::driver::funded;
fn post(bank:&mut EffectBank,turn:Turn,g:RetainedCloneGrant,heap:(usize,usize))->RetainedCloneProgress{let p=turn.result.unwrap().progress();bank.post(p,g,heap);p}
fn settled(turn:RetainedWorkPoll)->Turn{match turn{RetainedWorkPoll::Complete(turn)=>turn,RetainedWorkPoll::Pending{..}=>panic!("synchronous record turn stayed pending")}}
#[test]
fn actual_native_record_typed_backing_keeps_null_uninitialized_and_taken_ownership(){
 let law=law();let abi=law["abiCases"].as_array().unwrap().iter().find(|r|r["wordBytes"].as_u64().unwrap()as usize==std::mem::size_of::<usize>()).unwrap();let mut bank=EffectBank::new(Wallet::from_profile(&law["stock"]));let mut owner=NativeRecordStorage::<u64>::empty(1);let g=bank.loan(1,32768);
 let(denied,actual,heap)=funded(&mut bank,RetainedCloneGrant{maximum_items:0,..g},1,|effect|settled(owner.reserve_empty(effect)));assert_eq!(denied.work,0);assert_eq!(actual,None);assert_eq!(heap,(0,0));assert!(!owner.reserved());
 let(((poll,actual),attempts),heap)=crate::observe_retirement_allocations(||semio_framework_value_testing_allocator::refuse_one_allocation_on_this_thread(||bank.run(g,1,|effect|RetainedWorkPoll::Complete(settled(owner.reserve_empty(effect))))));assert_ne!(bank.take_admitted(),Some(false));let turn=settled(poll);assert_eq!(attempts,1);assert_eq!(actual,Some(0));assert_eq!(heap,(0,0));assert_eq!(turn.work,1);let p=turn.result.err().unwrap().retained_progress();bank.post(p,g,heap);assert!(!owner.reserved());
 let g=bank.loan(1,32768);let(turn,actual,heap)=funded(&mut bank,g,1,|effect|settled(owner.reserve_empty(effect)));assert_eq!(turn.work,law["allocationWork"].as_u64().unwrap().into());let p=post(&mut bank,turn,g,heap);assert_eq!(actual,Some(p.retained_capacity_bytes));
 let g=bank.loan(1,32768);let(turn,_,heap)=funded(&mut bank,g,1,|effect|owner.initialize(effect));assert_eq!(turn.work,law["initializeWork"].as_u64().unwrap().into());let p=post(&mut bank,turn,g,heap);assert_eq!(p.copied_bytes,1);
 let g=bank.loan(1,32768);let mut value=Some(law["value"].as_u64().unwrap());let d=NativeRecordStorage::<u64>::field_demand::<u64>(0).unwrap();assert_eq!(d.copy_bytes,abi["fieldCopy"].as_u64().unwrap()as usize);
 for denied in [RetainedCloneGrant{maximum_items:0,..g},RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes-1,..g}]{let(turn,_,heap)=funded(&mut bank,denied,3,|effect|unsafe{owner.place_field(0,&mut value,0,effect)});assert_eq!(turn.work,0);assert_eq!(heap,(0,0));assert!(turn.result.unwrap().is_none());assert_eq!(value,Some(42))}
 let g=bank.loan(1,32768);let(turn,_,heap)=funded(&mut bank,g,3,|effect|unsafe{owner.place_field(0,&mut value,0,effect)});assert_eq!(turn.work,law["placeWork"].as_u64().unwrap().into());let p=turn.result.unwrap().unwrap();assert_eq!(p.copied_bytes,d.copy_bytes);bank.post(p,g,heap);assert!(value.is_none());
 let mut removed:Option<u64>=None;let g=bank.loan(1,32768);let(denied,_,heap)=funded(&mut bank,RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes-1,..g},3,|effect|unsafe{owner.remove_field(0,&mut removed,0,effect)});assert_eq!(denied.work,0);assert_eq!(heap,(0,0));assert_eq!(denied.result.unwrap().progress(),Default::default());assert!(removed.is_none());
 let(turn,_,heap)=funded(&mut bank,g,3,|effect|unsafe{owner.remove_field(0,&mut removed,0,effect)});assert_eq!(turn.work,law["removeWork"].as_u64().unwrap().into());let p=post(&mut bank,turn,g,heap);assert_eq!(p.copied_bytes,abi["fieldCopy"].as_u64().unwrap()as usize);assert_eq!(removed,Some(42));
 let g=bank.loan(1,32768);let(incomplete,_,_)=funded(&mut bank,g,4,|effect|{let mut early=None;settled(unsafe{owner.take_initialized_into(&mut early,0,effect)})});assert!(incomplete.result.is_err());assert_eq!(incomplete.work,0);let(turn,_,heap)=funded(&mut bank,g,3,|effect|unsafe{owner.place_field(0,&mut removed,0,effect)});let p=turn.result.unwrap().unwrap();bank.post(p,g,heap);assert!(removed.is_none());
 let mut output=None;let g=bank.loan(1,32768);let(denied,_,heap)=funded(&mut bank,RetainedCloneGrant{maximum_items:0,..g},4,|effect|settled(unsafe{owner.take_initialized_into(&mut output,0,effect)}));assert_eq!(denied.work,0);assert_eq!(heap,(0,0));assert!(output.is_none());
 let(turn,_,heap)=funded(&mut bank,g,4,|effect|settled(unsafe{owner.take_initialized_into(&mut output,0,effect)}));assert_eq!(turn.work,law["takeWork"].as_u64().unwrap().into());let p=post(&mut bank,turn,g,heap);assert_eq!(serde_json::to_value(output.take().unwrap()).unwrap(),law["value"]);assert_eq!(p.copied_bytes,abi["takeCopy"].as_u64().unwrap()as usize);
 let g=bank.loan(1,32768);let(turn,_,heap)=funded(&mut bank,g,2,|effect|owner.release(effect));assert_eq!(turn.work,law["releaseWork"].as_u64().unwrap().into());let p=post(&mut bank,turn,g,heap);assert_eq!(p.copied_bytes,abi["releaseCopy"].as_u64().unwrap()as usize);assert!(owner.terminal_is_empty());assert!(owner.taken());assert!(bank.wallet().remaining_work()<law["stock"]["fuel"].as_u64().unwrap());
}
